import "./index.less"
import Accordion from './snippets/accordion-menu'

function animateFrom(elem, direction, gsap, pos) {
    direction = direction || 1;
    var x = 0,
        y = direction * 100;
    if (elem.classList.contains("gs_reveal_fromLeft")) {
        x = -100;
        y = 0;
    } else if (elem.classList.contains("gs_reveal_fromRight")) {
        x = 100;
        y = 0;
    }
    if (pos) {
        let x = pos.x || x + "px"
        let y = pos.y || y + "px"
        elem.style.transform = "translate(" + pos.x + "px, " + pos.y + "px)";
    }
    elem.style.transform = "translate(" + x + ", " + y + ")";
    elem.style.opacity = "0";
    gsap.fromTo(elem, {
        x: x,
        y: y,
        autoAlpha: 0
    }, {
        duration: 1.25,
        x: 0,
        y: 0,
        autoAlpha: 1,
        ease: "expo",
        overwrite: "auto"
    });
}

$(document).ready(function () {
    new Accordion($('.accordion-menu'), false);

    const faq_btn = $(".section-howToBuy-main .z-button-fill-middle")

    if ($('.faq-swiper-main .swiper-slide-active .accordion-menu li').length > 3) {
        $('.faq-main .z-button-fill-middle').css('display', 'flex')
    } else {
        $('.faq-main .z-button-fill-middle').css('display', 'none')
    }

    faq_btn.click(function () {
        const isActive = faq_btn.hasClass("active")
        if (isActive) {
            $(".faq-main .faq-swiper-main .swiper-slide-active .accordion-menu").removeClass("active")
            faq_btn.removeClass("active")
        } else {
            $(".faq-main .faq-swiper-main .swiper-slide-active .accordion-menu").addClass("active")
            faq_btn.addClass("active")
        }
    })
    var swiper = new Swiper(".swiper-thumbs", {
        slidesPerView: 'auto',
        freeMode: true,
        clickable: true,
    });

    var swiper2 = new Swiper(".faq-swiper-main", {
        spaceBetween: 0,
        slidesPerView: 1,
        thumbs: {
            swiper: swiper
        },
        on: {
            slideChangeTransitionEnd: function () {
                $(".faq-main .faq-swiper-main .accordion-menu").removeClass("active")
                faq_btn.removeClass("active")

                if ($('.faq-swiper-main .swiper-slide-active .accordion-menu li').length > 3) {
                    $('.faq-main .z-button-fill-middle').css('display', 'flex')
                } else {
                    $('.faq-main .z-button-fill-middle').css('display', 'none')
                }
            },
        },
    });

    gsap.registerPlugin(ScrollTrigger);
    gsap.utils.toArray(".gs_reveal").forEach(function (elem) {
        ScrollTrigger.create({
            trigger: elem,
            onEnter: function () {
                animateFrom(elem, 1, gsap)
            },
            onEnterBack: function () {
                animateFrom(elem, -1, gsap)
            }
        });
    });
})